int n, a[101], cnt[101];

void solve()
{
	cin >> n;

	for(int i = 1; i <= n; i ++)
	{
		cin >> a[i];
		cnt[a[i]] ++;
	}
	for(int i = 1; i <= n; i ++)
	{
