#include <bits/stdc++.h>

using namespace std;

void solve()
{
	int n;
	cin >> n;

	int a[n + 5];
	int pos[n + 5];

	for(int i = 1; i <= n; i ++)
	{
		cin >> a[i];
		pos[a[i]] = i % 2;
	}
	int balance = 0;

	for(int x = n; x > 0; x --)
	{
		if(pos[x] % 2 == 0) balance ++;
		if(pos[x] % 2 == 1) balance --;

		if(abs(balance) > 1)
		{
			cout << "NO\n";
			return;
		}
	}
	cout << "YES\n";
}
int main()
{
	int t;
	cin >> t;
	while(t --) solve();
}

