#define int long long
#define sz(x) (int)(x.size())
#define FOR( i, x, n, d ) for( int i = x; i <= n; i += d )
#define FORR( i, x, n, d ) for( int i = x; i >= n; i -= d )

using namespace std;

const int N = 2e5 + 12;
const int mod = 1e9 + 7;

int n, q, ans, cnt0, cnt1, pr[N];
string s;

void solve()
{
	cin >> n >> q >> s;
    ans = cnt0 = cnt1 = 0;

	FOR(i, 1, n - 1, 1)
	{
		pr[i] = 0;

		if(s[i - 1] != s[i])
		{
			pr[i] = 1;
			ans += i * (n - i);
		}
	}
	FOR(i, 0, n - 1, 1)
	{
	    if(s[i] == '0') cnt0 ++;
	    if(s[i] == '1') cnt1 ++;
	}
	cout << (ans + cnt0 * cnt1) / 2 << ' ';

	FOR(i, 1, q, 1)
	{
		int pos;
		cin >> pos;

		if(pos != 1)
		{
			if(pr[pos - 1] == 0) pr[pos - 1] = 1, ans += (pos - 1) * (n - pos + 1);
			else pr[pos - 1] = 0, ans -= (pos - 1) * (n - pos + 1);
		}
		if(pos != n)
		{
			if(pr[pos] == 0) pr[pos] = 1, ans += pos * (n - pos);
			else pr[pos] = 0, ans -= pos * (n - pos);
		}
		if(s[pos - 1] == '0') cnt0 --, cnt1 ++, s[pos - 1] = '1';
		else cnt1 --, cnt0 ++, s[pos - 1] = '0';

		cout << (ans + cnt0 * cnt1) / 2 << ' ';
	}
	cout << '\n';
}
signed main()
{
	ios_base::sync_with_stdio(0), cin.tie(0);

	int t = 0;
	if(!t) cin >> t;
	while(t --) solve();
}

