using namespace std;

const int N = 2048;
int n, m, tim, a[N], cnt[N], ans[N];

void transform()
{
	vector <int> v;

	for(int i = 1; i <= n; i ++)
	{
		for(int j = i + 1; j <= n; j ++)
		{
			v.push_back(a[i] ^ a[j]);
		}
	}
	sort(v.begin(), v.end());
	for(int i = 1; i <= n; i ++) a[i] = v[i - 1];
}
