	while(a[n] != 0)
	{
		lim ++, transform();
		ans[lim] = a[n] - a[1];
	}
	for(int i = 1; i <= m; i ++)
	{
		int x;
		cin >> x;

		if(x >= lim) cout << ans[lim] << '\n';
