#include <bits/stdc++.h>

using namespace std;

const int N = 3e5 + 12;

int n, m, tim, a[N], cnt[N], ans[N];
int t[N * 30], son[N * 30][2];

void update(int x, int v = 1)
{
	t[v] ++;

	for(int i = 29; i >= 0; i --)
	{
		if((x >> i) & 1)
		{
			if(!son[v][1]) son[v][1] = ++ tim;
			v = son[v][1];
		}
		else
		{
			if(!son[v][0]) son[v][0] = ++ tim;
			v = son[v][0];
		}
		t[v] ++;
	}
}
int get(int x, int k, int v = 1)
{
	int res = 0;

	for(int i = 29; i >= 0; i --)
	{
		int b = (x >> i) & 1;

		if(t[son[v][b]] >= k) v = son[v][b], res += (1 << i) * b;
		else k -= t[son[v][b]], v = son[v][b ^ 1], res += (1 << i) * (b ^ 1);
	}
	return res ^ x;
}
void transform()
{
	for(int v = 1; v <= tim; v ++) t[v] = son[v][0] = son[v][1] = 0;
	set <pair <int, int>> st; tim = 1;

	for(int i = 1; i <= n; i ++) update(a[i]), cnt[i] = 2;
	for(int i = 1; i <= n; i ++) st.insert({get(a[i], 2), i});

	vector <int> upd;

	for(int _ = 1; _ <= 2 * n; _ ++)
	{
		auto it = st.begin();
		int i = (*it).second;

		upd.push_back((*it).first);
		st.erase(it), cnt[i] ++;

		if(cnt[i] > n) continue;
		st.insert({get(a[i], cnt[i]), i});
	}
	for(int i = 1; i <= n; i ++) a[i] = upd[(i - 1) * 2];
}
void solve()
{
	cin >> n >> m;

	for(int i = 1; i <= n; i ++)
	{
		cin >> a[i];
	}
	sort(a + 1, a + n + 1);
	int lim = 0;

	ans[lim] = a[n] - a[1];

	while(a[n] != 0)
	{
		lim ++, transform();
		ans[lim] = a[n] - a[1];
	}
	for(int i = 1; i <= m; i ++)
	{
		int x;
		cin >> x;

		if(x >= lim) cout << ans[lim] << '\n';
		else cout << ans[x] << '\n';
	}
}
signed main()
{
	ios_base::sync_with_stdio(0), cin.tie(0);

	int test = 0;
	if(!test) cin >> test;
	while(test --) solve();
}

#include <bits/stdc++.h>

#define sz(x) (int)(x.size())
#define FOR( i, x, n, d ) for( int i = x; i <= n; i += d )
#define FORR( i, x, n, d ) for( int i = x; i >= n; i -= d )

using namespace std;

const int N = (1 << 20) + 5;
const int mod = 1e9 + 7;

int n, m, c[N], dp[N], cnt[N], st[N][21];

void add(int &x, int y)
{
    x += y;
    if(x >= mod) x -= mod;
}
void solve()
{
	cin >> n >> m;

	FOR( i, 1, m, 1 )
	{
		cin >> c[i];
	}
	dp[0] = cnt[0] = 1;

	FOR( i, 1, n, 1 )
	{
		st[i][0] = 0;

		FOR( j, 0, 19, 1 )
		{
			st[i][j + 1] = st[i][j];
			if(!((m >> j) & 1) || i < (1 << j)) continue;

			else
			{
			    add(st[i][j + 1], st[i - (1 << j)][j]);
			    add(st[i][j + 1], dp[i - (1 << j)]);
			}
		}
		dp[i] = st[i][20];
	}
	FOR( i, 1, n, 1 )
	{
		st[i][0] = 0;

		FOR( j, 0, 19, 1 )
		{
		    st[i][j + 1] = st[i][j];
			if(!((m >> j) & 1) || i < (1 << j)) continue;

			else
			{
			    add(st[i][j + 1], st[i - (1 << j)][j]);
			    add(st[i][j + 1], cnt[i - (1 << j)]);
			}
		}
		cnt[i] = st[i][20];
		add(cnt[i], dp[i]);
	}
	int ans = 0;

	FOR( i, 1, m, 1 )
	{
		if((m & i) == i) add(ans, c[i] * 1ll * cnt[n - i] % mod);
	}
	cout << ans << '\n';
}
signed main()
{
    ios_base::sync_with_stdio(0), cin.tie(0);

	int t = 0;
	if(!t) cin >> t;
	while(t --) solve();
}
